"use client";
import React, { useEffect, useState } from 'react';
import { useParams } from 'next/navigation';
import { db } from '@/firebase';
import { collection, getDocs, query, where } from 'firebase/firestore';
import Link from 'next/link';
import { ArrowLeft, Clock, Tag, Calendar, Share2, Copy, CheckCircle } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

export default function PoemPostClient() {
  const params = useParams();
  const slug = params?.slug;

  const [poem, setPoem] = useState(null);
  const [loading, setLoading] = useState(true);
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    if (!slug || slug === '_placeholder') return;

    const fetchPoem = async () => {
      try {
        const q = query(collection(db, 'poems'), where('slug', '==', slug));
        const snapshot = await getDocs(q);
        
        if (!snapshot.empty) {
          const postData = { id: snapshot.docs[0].id, ...snapshot.docs[0].data() };
          setPoem(postData);

          // Update SEO tags dynamically
          document.title = `${postData.title} | Poetry by Suleman Zaheer`;
          
          let metaDesc = document.querySelector('meta[name="description"]');
          if (!metaDesc) {
            metaDesc = document.createElement('meta');
            metaDesc.name = 'description';
            document.head.appendChild(metaDesc);
          }
          const contentStr = postData.content || '';
          metaDesc.content = contentStr.substring(0, 150).replace(/\n/g, ' ');
        } else {
          setPoem(null);
        }
      } catch (error) {
        console.error("Error fetching poem:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchPoem();
  }, [slug]);

  const generateSchema = () => {
    if (!poem) return null;
    return {
      '@context': 'https://schema.org',
      '@type': 'CreativeWork',
      additionalType: 'Poem',
      headline: poem.title,
      text: poem.content,
      inLanguage: poem.language === 'Urdu' ? 'ur' : 'en',
      author: {
        '@type': 'Person',
        name: 'Suleman Zaheer',
        url: 'https://suleman-zaheer.web.app',
      },
      publisher: {
        '@type': 'Organization',
        name: 'Suleman Zaheer',
      },
      datePublished: poem.publishedAt?.toDate ? poem.publishedAt.toDate().toISOString() : new Date().toISOString(),
      mainEntityOfPage: {
        '@type': 'WebPage',
        '@id': `https://suleman-zaheer.web.app/poetry/${poem.slug}`
      }
    };
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-neutral-950 flex items-center justify-center">
        <div className="w-12 h-12 border-4 border-rose-400/20 border-t-rose-400 rounded-full animate-spin" />
      </div>
    );
  }

  if (!poem) {
    return (
      <div className="min-h-screen bg-neutral-950 flex flex-col items-center justify-center text-white px-4">
        <h1 className="text-4xl font-bold mb-4 font-display">Kalam Not Found</h1>
        <p className="text-gray-400 mb-8">The poem you are looking for does not exist or has been removed.</p>
        <Link href="/poetry" className="px-6 py-3 bg-rose-500 text-white font-bold rounded-xl hover:bg-rose-600 transition-colors">
          Back to Poetry
        </Link>
      </div>
    );
  }

  const formattedDate = poem.publishedAt?.toDate 
    ? new Date(poem.publishedAt.toDate()).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' }) 
    : 'Recently';

  const isUrdu = poem.language === 'Urdu' || poem.language?.includes('Mixed');
  
  const handleCopy = () => {
    navigator.clipboard.writeText(`${poem.title}\n\n${poem.content}\n\n- Suleman Zaheer`);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <main className="min-h-screen bg-neutral-950 text-white font-sans selection:bg-rose-400/30 pb-24 relative overflow-hidden">
      {/* Background decorations */}
      <div className="fixed top-[-20%] right-[-10%] w-[50%] h-[50%] rounded-full bg-rose-500/5 blur-[120px] pointer-events-none" />
      <div className="fixed bottom-[-20%] left-[-10%] w-[50%] h-[50%] rounded-full bg-violet-500/5 blur-[120px] pointer-events-none" />

      {generateSchema() && (
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{ __html: JSON.stringify(generateSchema()) }}
        />
      )}

      {/* Toast */}
      <AnimatePresence>
        {copied && (
          <motion.div initial={{ opacity: 0, y: -20, x: '-50%' }} animate={{ opacity: 1, y: 0, x: '-50%' }} exit={{ opacity: 0, y: -20, x: '-50%' }}
            className="fixed top-24 left-1/2 z-50 px-5 py-3 rounded-full text-xs font-bold flex items-center gap-2 shadow-2xl bg-rose-400/20 border border-rose-400/30 text-rose-300">
            <CheckCircle size={14} /> Kalam copied to clipboard!
          </motion.div>
        )}
      </AnimatePresence>

      <article className="pt-32 max-w-3xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
        <Link href="/poetry" className="inline-flex items-center gap-2 text-gray-400 hover:text-rose-400 transition-colors mb-12 font-medium">
          <ArrowLeft size={18} /> Back to Collection
        </Link>
        
        <div className="text-center mb-16">
          <div className="flex flex-wrap items-center justify-center gap-3 mb-6">
            <span className="px-4 py-1.5 rounded-full bg-rose-400/10 border border-rose-400/20 text-rose-400 text-xs font-black uppercase tracking-wider">
              {poem.type}
            </span>
            <span className="px-4 py-1.5 rounded-full bg-white/5 border border-white/10 text-gray-400 text-xs font-bold">
              {poem.language}
            </span>
            {poem.theme && (
              <span className="px-4 py-1.5 rounded-full bg-white/5 border border-white/10 text-gray-400 text-xs italic">
                {poem.theme}
              </span>
            )}
          </div>

          <h1 className="text-4xl sm:text-5xl md:text-6xl font-display font-black leading-tight mb-8" dir={isUrdu ? "rtl" : "ltr"}>
            {poem.title}
          </h1>

          <div className="flex items-center justify-center gap-4 text-sm text-gray-500">
            <span className="flex items-center gap-1.5">
              <Calendar size={14} className="text-rose-400" />
              {formattedDate}
            </span>
          </div>
        </div>

        {/* Poem Content */}
        <div className="bg-white/[0.02] border border-white/10 rounded-3xl p-8 sm:p-12 mb-12 relative backdrop-blur-sm">
          <div className={`text-lg sm:text-xl md:text-2xl leading-relaxed sm:leading-loose md:leading-loose whitespace-pre-wrap ${isUrdu ? 'font-urdu text-right' : 'text-center'}`} dir={isUrdu ? 'rtl' : 'ltr'}>
            {poem.content}
          </div>
        </div>

        {/* Actions & Footer */}
        <div className="flex flex-col sm:flex-row items-center justify-between gap-6 border-t border-white/10 pt-8 mt-12">
          {poem.tags && poem.tags.length > 0 && (
            <div className="flex flex-wrap gap-2 justify-center sm:justify-start">
              {poem.tags.map(tag => (
                <span key={tag} className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-white/5 border border-white/5 text-xs text-gray-400">
                  <Tag size={10} className="text-rose-400" />
                  {tag}
                </span>
              ))}
            </div>
          )}
          
          <div className="flex items-center gap-3">
            <button onClick={handleCopy} className="flex items-center gap-2 px-4 py-2 rounded-xl bg-white/5 border border-white/10 text-sm font-bold text-gray-300 hover:bg-rose-400/20 hover:text-rose-400 hover:border-rose-400/30 transition-all">
              <Copy size={16} /> Copy
            </button>
            <button onClick={() => {
              if (navigator.share) {
                navigator.share({ title: poem.title, url: window.location.href })
              }
            }} className="flex items-center gap-2 px-4 py-2 rounded-xl bg-white/5 border border-white/10 text-sm font-bold text-gray-300 hover:bg-rose-400/20 hover:text-rose-400 hover:border-rose-400/30 transition-all">
              <Share2 size={16} /> Share
            </button>
          </div>
        </div>
      </article>
    </main>
  );
}
